from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
home=(root/'dist/index.html').read_text(encoding='utf-8')
head=home.split('<body>')[0]
header=re.search(r'<header[\s\S]*?</header>',home)[0].replace('href="#','href="/#')
footer=re.search(r'<footer[\s\S]*?</footer>',home)[0].replace('href="#','href="/#')
def write(slug,title,content):
 h=re.sub(r'<title>.*?</title>',f'<title>{title} — Rasio Labs</title>',head)
 (root/f'dist/{slug}.html').write_text(h+'<body class="info-page"><a class="skip-link" href="#main-content">Lewati ke konten utama</a>'+header+'<main id="main-content">'+content+'</main>'+footer+'<script src="/navigation.js?v=15"></script></body></html>',encoding='utf-8')
steps=[
 ('Pilih layanan dan desain','Mulai dari RasioLabs Store atau RasioLabs Profile. Pilih template langsung dari koleksi, atau tentukan desain setelah memilih domain.'),
 ('Tentukan domain website','Di halaman pemesanan, cukup ketik nama bisnis lalu pilih ekstensi. Domain gratis selama 1 tahun untuk paket 12 bulan atau lebih; paket 1 bulan memakai domain berbayar untuk 1 tahun. 1 email bisnis gratis selama langganan aktif.'),
 ('Sesuaikan kebutuhan toko','Untuk RasioLabs Store, Anda dapat menambahkan RasioLabs AI Insight seharga Rp500.000/tahun. AI chatbot sudah termasuk dalam paket pre-made.'),
 ('Isi data dan lakukan pembayaran','Lengkapi nama bisnis, penanggung jawab, WhatsApp, dan email. Periksa pilihan serta biaya sebelum membayar. Tidak perlu membuat akun manual.'),
 ('Kirim materi dan review website','Tim menghubungi Anda dalam 1 × 24 jam setelah pembayaran. Siapkan logo, copywriting, foto, dan produk agar setup serta review berjalan lancar.'),
 ('Website aktif dan siap dikelola','Website pre-made aktif dalam 1–2 × 24 jam setelah pemesanan. Anda menerima akses CMS atau dashboard, email bisnis, dan panduan penggunaan.')]
cards=''.join(f'<article class="tutorial-card"><span>{i:02}</span><h2>{t}</h2><p>{c}</p><i class="flow-arrow" aria-hidden="true">→</i></article>' for i,(t,c) in enumerate(steps,1))
write('tutorial','Tutorial pemesanan',f'''<section class="info-hero"><div class="shell"><p class="eyebrow">Tutorial / pemesanan pre-made</p><h1>Pelajari cara memesan website dan <mark class="marker">menyiapkan materi bisnis Anda.</mark></h1><p>Panduan ini menjelaskan pemesanan website, mulai dari memilih layanan hingga menerima akses pengelolaan. Tim Rasio Labs menyiapkan website berdasarkan materi Anda dan memberikan panduan penggunaannya.</p></div></section><div class="shell tutorial-grid">{cards}</div><div class="shell tutorial-notes"><article><p class="eyebrow">Setelah website aktif</p><h2>Kelola konten lewat CMS.</h2><p>Pada RasioLabs Profile, Anda dapat memperbarui teks, gambar, dan logo melalui CMS. Pada RasioLabs Store, dashboard digunakan untuk mengelola produk, stok, dan pesanan. Maintenance teknis termasuk selama langganan aktif.</p><a class="secondary-button" href="/#template">Lihat template website →</a></article><article><p class="eyebrow">Untuk kebutuhan khusus</p><h2>Website, ERP, atau software custom?</h2><p>Mulai dengan konsultasi. Kami menyusun fitur, biaya, dan jadwal berdasarkan cakupan proyek. Estimasi aktivasi pre-made tidak berlaku untuk pengembangan custom.</p><a class="secondary-button" href="/layanan-custom.html">Pelajari RasioLabs Custom →</a></article></div>''')
write('portofolio','Portofolio dan preview desain','''<section class="info-hero"><div class="shell"><p class="eyebrow">Portofolio / preview karya</p><h1>Lihat contoh desain website dan software <mark class="marker">untuk kebutuhan bisnis Anda.</mark></h1><p>Pelajari contoh desain website dan prototipe software sebelum memilih layanan. Koleksi ini merupakan pengembangan desain Rasio Labs, bukan daftar proyek klien yang telah diluncurkan.</p></div></section><div class="shell portfolio-grid"><article class="portfolio-card"><div class="portfolio-art"><img src="/assets/architecture-exterior.jpg" alt="Architecture Studio — Designed for Better Living" /></div><span class="dummy-badge">Company profile · Arsitektur &amp; Interior</span><h2>Architecture Studio — Designed for Better Living</h2><p>Website untuk studio arsitektur dan interior, dengan galeri ruang, layanan, dan kontak.</p><a class="secondary-button" href="/template-architecture.html">Lihat website →</a></article><article class="portfolio-card"><div class="portfolio-art"><img src="/assets/rasio-flow.png" alt="Preview dashboard software Rasio Labs Flow" /></div><span class="dummy-badge">Prototipe · Software</span><h2>Rasio Labs Flow</h2><p>Preview dashboard untuk alur pesan dan automasi yang membantu tim menjalankan operasional.</p><a class="secondary-button" href="/layanan-custom.html">Pelajari layanan →</a></article></div>''')
print('Generated Tutorial and Portfolio.')
